// Precomputes the reproduction matrix: every city case generated by every code.
// Output: src/data/matrix.json (consumed by the app; regenerated on every build).
import { writeFileSync } from 'node:fs';
import { generate } from '../src/engine/generate';
import { CODES } from '../src/engine/codes';
import { CITY_CASES } from '../src/data/cases';

const r = (x: number, d = 3) => Math.round(x * 10 ** d) / 10 ** d;
const out: Record<string, unknown> = {};
const t0 = Date.now();
for (const c of CITY_CASES) {
  for (const code of CODES) {
    const m = generate(c.theta!, code.id);
    out[`${c.id}:${code.id}`] = {
      e: r(m.error),
      p: Object.fromEntries(Object.entries(m.errors).map(([k, v]) => [k, r(v)])),
      m: { O: r(m.measured.O), I: r(m.measured.I), E: r(m.measured.E), H: r(m.measured.H), G: r(m.measured.G, 1), wall: r(m.measured.wall, 2) },
      k: { a: r(m.knobs.a, 4), k: r(m.knobs.k, 4) },
    };
  }
}
writeFileSync(new URL('../src/data/matrix.json', import.meta.url), JSON.stringify(out));
console.log(`matrix: ${Object.keys(out).length} runs in ${Date.now() - t0} ms`);
